import { Component, Event, EventEmitter, h, Listen, Method, Prop, Watch } from '@stencil/core';

@Component({
  tag: 'std-modal-native',
  styleUrl: 'std-modal-native.css',
  shadow: true
})
export class StdModalNativeComponent {
  private dialogElement: HTMLDialogElement;

  @Prop() size = 's';
  @Prop() noHeader: boolean;
  @Prop() noFooter: boolean;
  @Prop() classes: string;
  @Prop() modalClasses: string;
  @Prop() classContent: string;
  @Prop() show: boolean;
  @Prop() closeableEsc: boolean;

  @Event({bubbles: false}) iconClick: EventEmitter;

  @Method()
  async openDialog() {
    if(this.dialogElement) {
      this.dialogElement.showModal();
      this.dialogElement.focus();
      this.dialogElement.blur();
    }
  }

  @Method()
  async closeDialog() {
    this.dialogElement && this.dialogElement.close();
  }

  @Watch('show')
  handleShowChange(newValue: boolean) {
    newValue ? this.openDialog() : this.closeDialog();
  }

  @Listen('keydown', { target: 'document', capture: true })
  handleScroll(ev: KeyboardEvent) {
    if (ev.code === 'Escape') {
      !this.closeableEsc ? ev.preventDefault() : this.closeDialog();
    }
  }

  componentDidLoad() {
    if (this.show) {
      this.openDialog();
    }
  }

  render() {
    const containerSizeClasses = {
      s: 'lg:max-w-[25rem]',
      m: 'lg:max-w-[37.5rem]',
      l: 'lg:max-w-[50rem]'
    }[this.size];

    const containerClasses = ['flex flex-col w-full mx-auto bg-white rounded-t-lg lg:rounded-lg shadow-modal overflow-hidden', containerSizeClasses, this.classes]
      .join(' ')
      .trim()
      .replace(/\s+/g, ' ');

    const dialogClasses = ['css-modal-native fixed inset-0 backdrop:bg-dark/50 bg-transparent z-20 focus:outline-none', this.modalClasses].join(' ').trim().replace(/\s+/g, ' ');

    const footerClasses = ['flex flex-col lg:flex-row lg:flex-wrap gap-4 px-4 pt-4 pb-6 lg:px-6 lg:pt-6 lg:pb-8', this.size === 's' ? 'lg:justify-center' : 'lg:justify-end']
      .join(' ')
      .trim()
      .replace(/\s+/g, ' ');

    return (
      <dialog ref={el => (this.dialogElement = el as HTMLDialogElement)} class={dialogClasses}>
        <div class={containerClasses}>
          {!this.noHeader && (
            <header class="flex justify-end p-2 lg:p-6">
              <button class="flex justify-center items-center focus:outline-none" data-modal-close onClick={e => this.iconClick.emit(e)}>
                <i class="icon-close text-2xl leading-none " />
              </button>
            </header>
          )}

          <div
            class={['px-4 pb-4 lg:px-6 lg:pb-6', this.noHeader ? 'pt-6 lg:pt-8' : '', this.noFooter ? 'pb-6 lg:pb-8' : '', this.classContent]
              .join(' ')
              .trim()
              .replace(/\s+/g, ' ')}>
            <slot />
          </div>

          {!this.noFooter && (
            <footer class={footerClasses}>
              <slot name="footer" />
            </footer>
          )}
        </div>
      </dialog>
    );
  }
}
